    ("docs", "docs: add docs/ACCESSIBILITY.md a11y commitments", "docs/ACCESSIBILITY.md", "# Accessibility\n\n## Commitments\n- CLI output screen-reader friendly (no decorative unicode in --json mode)\n- Web UI targets WCAG 2.1 AA\n- Keyboard-only operation supported\n- High-contrast theme available\n\n## Reporting issues\nOpen an issue labeled 'a11y'. Prioritized by maintainer.\n"),
    ("feat", "feat: add scripts/check-md-links.sh validate docs cross-refs", "scripts/check-md-links.sh", "#!/usr/bin/env bash\nset -euo pipefail\necho 'Checking markdown link targets...'\nfor f in docs/*.md *.md; do\n  [ -f \"$f\" ] || continue\n  grep -oE '\\[.+\\]\\(([^)]+)\\)' \"$f\" | while IFS= read -r line; do\n    target=$(echo \"$line\" | sed 's/.*)\\(//;s/)//')\n    [ -e \"$target\" ] || echo \"  $f: broken -> $target\"\n  done\ndone\necho 'Check complete.'\n"),
    ("docs", "docs: add docs/DEPENDENCIES.md third-party deps + licenses", "docs/DEPENDENCIES.md", "# Dependencies & Licenses\n\n| Crate | Version | License | Purpose |\n|---|---|---|---|\n| tokio | 1.x | MIT | Async runtime |\n| serde | 1.x | MIT | Serialization |\n| reqwest | 0.12 | MIT | HTTP client |\n| ratatui | 0.29 | MIT | TUI rendering |\n| clap | 4.x | MIT | CLI parsing |\n\nAll deps MIT or Apache-2.0 compatible. No GPL/AGPL deps.\n"),
